 private void loadMissions(){missions.removeAllViews();missions.addView(label("Missões",21,0xfff5f1ff));LinearLayout tabs=new LinearLayout(getContext());for(boolean week:new boolean[]{false,true}){Button tab=button(week?"Semana":"Hoje",weekly==week);tabs.addView(tab,new LinearLayout.LayoutParams(0,dp(44),1));tab.setOnClickListener(v->{weekly=week;loadMissions();});}missions.addView(tabs);TextView loading=label("Carregando missões…",13,0xffbcb3c9);missions.addView(loading);final int request=++missionRequest;final boolean selectedWeek=weekly;repo.missions(selectedWeek,(rows,error)->{if(request!=missionRequest)return;loading.setText(error==null?"":error);if(error!=null)return;String expectedPrefix=selectedWeek?"semana:":"";int shown=0;for(int i=0;i<rows.length();i++){JSONObject m=rows.optJSONObject(i);String missionPeriod=m==null?"":m.optString("periodo");if(m==null||missionPeriod.startsWith("semana:")!=selectedWeek||(!selectedWeek&&missionPeriod.contains(":")))continue;String key=m.optString("missao_id");int amount=MissionPolicy.goal(key),goal=Math.max(1,m.optInt("meta",amount)),xp=Math.max(1,m.optInt("xp",MissionPolicy.xp(key))),value=Math.max(0,m.optInt("progresso"));boolean claimed=m.optBoolean("reivindicada");LinearLayout tile=panel(missions);tile.addView(label(MissionPolicy.icon(key)+" "+m.optString("nome","Missão"),16,0xfff5efff));tile.addView(label(m.optString("objetivo",MissionPolicy.objective(key,goal)),12,0xffc8bfd3));tile.addView(label("+"+xp+" XP  •  "+Math.min(value,goal)+" / "+goal,12,0xffbbabdb));bar(tile,Math.min(100,value*100/goal));Button claim=button(claimed?"Recompensa recebida":value>=goal?"Resgatar +"+xp+" XP":"Em andamento",value>=goal&&!claimed);claim.setEnabled(value>=goal&&!claimed);tile.addView(claim);claim.setOnClickListener(v->{claim.setEnabled(false);repo.claimMission(m.optString("id"),(result,e)->{if(e!=null){loading.setText(e);return;}JSONObject confirmation=result.optJSONObject(0);if(confirmation==null||!confirmation.optBoolean("sucesso")){loading.setText(confirmation==null?"Resgate sem confirmação.":confirmation.optString("mensagem","Resgate indisponível."));return;}loadMissions();ranking();});});shown++;}if(shown==0)loading.setText("Nenhuma missão disponível neste período. Atualize para tentar novamente.");});}
 private static String period(boolean week){Calendar c=Calendar.getInstance();if(week){int day=(c.get(Calendar.DAY_OF_WEEK)+5)%7;c.add(Calendar.DAY_OF_MONTH,-day);}return (week?"semana:":"")+String.format(Locale.ROOT,"%04d-%02d-%02d",c.get(Calendar.YEAR),c.get(Calendar.MONTH)+1,c.get(Calendar.DAY_OF_MONTH));}
 private LinearLayout section(){return panel(body);}private LinearLayout panel(LinearLayout parent){LinearLayout box=new LinearLayout(getContext());box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(16),dp(16),dp(16),dp(16));box.setBackground(AppStyle.shape(box,0xff211b2d,22));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,0,0,dp(14));parent.addView(box,lp);return box;}
 private void bar(LinearLayout parent,int value){ProgressBar b=new ProgressBar(getContext(),null,android.R.attr.progressBarStyleHorizontal);b.setMax(100);b.setProgress(value);b.setProgressTintList(android.content.res.ColorStateList.valueOf(0xffa774f3));parent.addView(b,new LinearLayout.LayoutParams(-1,dp(8)));}
 private TextView label(String value,int size,int color){TextView t=NativeSheet.text(getContext(),value,size,color);t.setPadding(0,dp(5),0,dp(5));return t;}private Button button(String value,boolean primary){Button b=new Button(getContext());b.setText(value);b.setTextSize(12);AppStyle.button(b,primary);return b;}private int dp(int value){return AppStyle.dp(this,value);}
